/** Página de la Oficina (generada desde el diseño aprobado). */
export const OFICINA_HTML = "<!doctype html><html lang=\"es\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"robots\" content=\"noindex,nofollow\"><script>\n/* Conexión de la Oficina con la base propia (reemplaza la base de la página de Claude): lee cada pocos segundos y escribe por la API. */\n(function(){\n  var API='/api/oficina/db/';\n  function req(m,u,b){ return fetch(u,{method:m,credentials:'same-origin',cache:'no-store',headers:b?{'content-type':'application/json'}:undefined,body:b?JSON.stringify(b):undefined}).then(function(r){ if(r.status===401){ location.reload(); throw new Error('401'); } if(!r.ok) throw new Error(String(r.status)); return r.json(); }); }\n  function Q(c){ this.c=c; this.o=''; this.d='desc'; this.l=200; }\n  Q.prototype.orderBy=function(f,d){ this.o=f; this.d=d||'asc'; return this; };\n  Q.prototype.limit=function(n){ this.l=n; return this; };\n  Q.prototype.add=function(obj){ return req('POST',API+this.c,obj); };\n  Q.prototype.onSnapshot=function(ok,err){\n    var self=this, stop=false;\n    function tick(){\n      req('GET',API+self.c+'?o='+encodeURIComponent(self.o)+'&d='+self.d+'&l='+self.l).then(function(j){\n        ok({docs:j.docs.map(function(d){ return {id:d.id,data:function(){ return d.data; }}; }),metadata:{fromCache:false}});\n      }).catch(function(e){ if(err) err({code:e&&e.message||'error'}); }).then(function(){ if(!stop) setTimeout(tick,document.hidden?20000:5000); });\n    }\n    tick(); return function(){ stop=true; };\n  };\n  var db={ collection:function(c){ return new Q(c); }, doc:function(p){ var a=p.split('/'); return { update:function(patch){ return req('PATCH',API+a[0]+'/'+encodeURIComponent(a[1]),patch); } }; } };\n  var user={ isOwner:function(){ return true; }, can:function(){ return true; } };\n  window.claude={ use:function(n){ return Promise.resolve(n==='db'?db:user); } };\n})();\n</script>\n<title>Oficina DEVISEBIT</title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700&family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@400;500;600&display=swap\">\n<style>\n/* Plano de oficina por pisos: arriba lo que espera una decisión, debajo un piso por equipo, cada agente en su escritorio. */\n:root{\n  --bg:#F1F2F4; --surface:#FFFFFF; --surface2:#E7E9ED; --ink:#15171C; --muted:#5A616E; --line:#D3D7DE;\n  --brand:#D7263D; --btn:#15171C; --btn-ink:#FFFFFF;\n  --wall:#E9ECF2; --wall2:#DDE2EB; --flr:#B9A58A; --flr2:#A8947A; --dsk:#8B6B4A; --dsk2:#A9855F; --glass:#CFE6FF; --bld:#2A2F3A;\n  --st-work:#1E6FD9; --st-done:#12935A; --st-wait:#B86E00; --st-err:#D1343B; --st-idle:#8A919E;\n  --f-display:\"Bricolage Grotesque\",\"Helvetica Neue\",Arial,sans-serif;\n  --f-body:\"IBM Plex Sans\",\"Helvetica Neue\",Arial,sans-serif;\n  --f-mono:\"IBM Plex Mono\",ui-monospace,Menlo,Consolas,monospace;\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    --bg:#0D0E11; --surface:#16181D; --surface2:#1F2229; --ink:#ECEEF2; --muted:#9AA1AE; --line:#2B2F38;\n    --brand:#FF5468; --btn:#ECEEF2; --btn-ink:#0D0E11;\n    --wall:#1B2030; --wall2:#232A3D; --flr:#3A3128; --flr2:#2F281F; --dsk:#5A4430; --dsk2:#6E5339; --glass:#1E3350; --bld:#07080B;\n    --st-work:#5AA2FF; --st-done:#3DD598; --st-wait:#F5A524; --st-err:#FF6B72; --st-idle:#7C8493;\n    color-scheme:dark;\n  }\n}\n:root[data-theme=\"dark\"]{\n  --bg:#0D0E11; --surface:#16181D; --surface2:#1F2229; --ink:#ECEEF2; --muted:#9AA1AE; --line:#2B2F38;\n  --brand:#FF5468; --btn:#ECEEF2; --btn-ink:#0D0E11;\n  --wall:#1B2030; --wall2:#232A3D; --flr:#3A3128; --flr2:#2F281F; --dsk:#5A4430; --dsk2:#6E5339; --glass:#1E3350; --bld:#07080B;\n  --st-work:#5AA2FF; --st-done:#3DD598; --st-wait:#F5A524; --st-err:#FF6B72; --st-idle:#7C8493;\n  color-scheme:dark;\n}\n*{box-sizing:border-box}\nbody{background:var(--bg);color:var(--ink);font:15px/1.45 var(--f-body);padding-block:20px 48px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}\n.wrap{max-width:1100px;margin:0 auto;display:flex;flex-direction:column;gap:26px}\nh1,h2,h3{font-family:var(--f-display);margin:0;text-wrap:balance}\nbutton,input,select,textarea{font:inherit;color:inherit}\nbutton{cursor:pointer}\n:focus-visible{outline:2px solid var(--st-work);outline-offset:2px}\n\n/* cabecera */\n.top{display:flex;flex-wrap:wrap;gap:14px 24px;align-items:flex-end;justify-content:space-between}\n.brand{display:flex;flex-direction:column;gap:4px;min-width:0}\n.kicker{font:500 12px var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted);display:flex;align-items:center;gap:8px}\n.kicker::before{content:\"\";width:8px;height:8px;background:var(--brand);border-radius:2px}\nh1{font-size:clamp(28px,6vw,40px);line-height:1.05;font-weight:700}\n.counts{display:flex;flex-wrap:wrap;gap:8px}\n.pill{display:flex;align-items:center;gap:8px;padding:7px 12px;border:1px solid var(--line);background:var(--surface);border-radius:999px;font:500 13px var(--f-mono)}\n.pill b{font-size:15px}\n.dot{width:9px;height:9px;border-radius:50%;background:var(--c,var(--st-idle));flex:none}\n.sync{font:400 12px var(--f-mono);color:var(--muted)}\n.sync[data-bad=\"1\"]{color:var(--st-wait)}\n\n/* bloques */\n.block{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:16px;display:flex;flex-direction:column;gap:12px}\n.block h2{font-size:19px;font-weight:600}\n.sub{color:var(--muted);font-size:13px;margin:0}\n.attn{border-color:var(--st-wait)}\n.attn-list{display:flex;flex-direction:column;gap:8px}\n.attn-item{display:flex;gap:10px;align-items:flex-start;padding:10px 12px;background:var(--surface2);border-radius:8px}\n.attn-item .dot{margin-top:6px}\n.attn-item p{margin:0;min-width:0;overflow-wrap:anywhere}\n.attn-item small{display:block;color:var(--muted);font:400 12px var(--f-mono);margin-top:2px}\n.calm{color:var(--muted);margin:0}\n\n/* órdenes */\n.compose{display:flex;flex-direction:column;gap:8px}\ntextarea{width:100%;min-height:76px;resize:vertical;background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:10px 12px}\n.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}\n.btn{background:var(--btn);color:var(--btn-ink);border:0;border-radius:8px;padding:9px 16px;font-weight:600}\n.btn.ghost{background:transparent;color:var(--ink);border:1px solid var(--line)}\n.btn[disabled]{opacity:.45;cursor:not-allowed}\n.orders{display:flex;flex-direction:column;gap:10px}\n.order{border:1px solid var(--line);border-radius:8px;padding:12px;display:flex;flex-direction:column;gap:8px;min-width:0}\n.order p{margin:0;overflow-wrap:anywhere}\n.chip{align-self:flex-start;font:500 11px var(--f-mono);letter-spacing:.04em;text-transform:uppercase;padding:3px 8px;border-radius:999px;border:1px solid var(--c,var(--line));color:var(--c,var(--muted))}\n.reparto{margin:0;padding-left:18px;display:flex;flex-direction:column;gap:4px;font-size:14px}\n.reparto b{font-weight:600}\n.meta{font:400 12px var(--f-mono);color:var(--muted)}\n\n/* edificio: cada piso es una sala con escritorios */\n.building{background:var(--bld);border-radius:14px;padding:8px;display:flex;flex-direction:column;gap:6px;box-shadow:0 10px 30px rgba(0,0,0,.18)}\n.floor{display:grid;grid-template-columns:44px 1fr;gap:0;border-radius:8px;overflow:hidden;background:var(--wall)}\n.plate{background:var(--bld);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;font:600 11px var(--f-mono);padding:6px 0;border-right:2px solid var(--brand)}\n.plate b{font:700 24px var(--f-display);line-height:1}\n.room{position:relative;min-width:0;background:\n  linear-gradient(var(--wall) 0 72%,var(--flr) 72% 100%);padding:10px 10px 0}\n.room::before{content:\"\";position:absolute;left:0;right:0;top:0;height:72%;background:\n  repeating-linear-gradient(90deg,transparent 0 86px,var(--wall2) 86px 88px);opacity:.7;pointer-events:none}\n.room::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:28%;background:repeating-linear-gradient(90deg,var(--flr2) 0 2px,transparent 2px 60px);opacity:.5;pointer-events:none}\n.rhead{position:relative;z-index:1;display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 10px;margin-bottom:4px}\n.rhead h2{font-size:18px;font-weight:700}\n.rhead .fc{margin-left:auto;font:500 11px var(--f-mono);color:var(--muted);background:var(--surface);padding:2px 8px;border-radius:999px;border:1px solid var(--line)}\n.desks{position:relative;z-index:1;display:grid;grid-template-columns:repeat(auto-fill,minmax(132px,1fr));gap:0 6px}\n.wk{all:unset;box-sizing:border-box;cursor:pointer;position:relative;display:flex;flex-direction:column;align-items:center;min-width:0;padding-top:4px}\n.wk:focus-visible{outline:2px solid var(--st-work);outline-offset:-2px;border-radius:8px}\n.bub{position:relative;max-width:100%;min-height:34px;display:flex;align-items:center;justify-content:center;text-align:center;font-size:11.5px;line-height:1.25;background:var(--surface);color:var(--ink);border:1.5px solid var(--c);border-radius:10px;padding:5px 8px;overflow-wrap:anywhere;box-shadow:0 2px 0 rgba(0,0,0,.08)}\n.bub::after{content:\"\";position:absolute;left:50%;bottom:-6px;width:9px;height:9px;background:var(--surface);border-right:1.5px solid var(--c);border-bottom:1.5px solid var(--c);transform:translateX(-50%) rotate(45deg)}\n.bub span{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}\n.who{position:relative;width:100%;height:122px;margin-top:6px}\n.av2{position:absolute;left:50%;bottom:48px;width:62px;height:62px;margin-left:-31px;z-index:1;transform-origin:50% 100%}\n.av2 svg{width:62px;height:62px;display:block;overflow:visible}\n.dk{position:absolute;left:6%;right:6%;bottom:0;height:34px;z-index:3}\n.dk .top{position:absolute;left:0;right:0;top:0;height:11px;background:var(--dsk2);border-radius:4px 4px 2px 2px;box-shadow:0 2px 0 rgba(0,0,0,.18)}\n.dk .leg{position:absolute;left:8%;right:8%;top:11px;bottom:0;background:var(--dsk);border-radius:0 0 3px 3px}\n.mon{position:absolute;left:50%;bottom:30px;width:40px;height:22px;margin-left:-20px;background:#1b1e25;border-radius:4px;border:2px solid #2d313b;z-index:2;overflow:hidden;box-shadow:0 0 0 0 var(--c)}\n.mon::after{content:\"\";position:absolute;left:50%;bottom:-6px;width:8px;height:4px;margin-left:-4px;background:#2d313b}\n.mon i{position:absolute;left:4px;height:3px;border-radius:2px;background:var(--c);opacity:.35}\n.mon i:nth-child(1){top:3px;width:24px}.mon i:nth-child(2){top:8px;width:16px}.mon i:nth-child(3){top:13px;width:28px}\n.tag{position:relative;z-index:4;margin-top:-2px;max-width:100%;text-align:center;background:var(--surface);border:1px solid var(--line);border-bottom:3px solid var(--c);border-radius:6px;padding:3px 8px 4px;min-width:0}\n.tag b{display:block;font:600 12px var(--f-display);line-height:1.15;overflow-wrap:anywhere}\n.tag small{display:block;font:500 9.5px var(--f-mono);letter-spacing:.05em;text-transform:uppercase;color:var(--c)}\n.badge{position:absolute;z-index:5;right:14%;top:-6px;width:20px;height:20px;border-radius:50%;background:var(--c);color:#fff;display:none;align-items:center;justify-content:center;font:700 12px var(--f-mono)}\n.wk[data-st=\"waiting_user\"] .badge,.wk[data-st=\"error\"] .badge,.wk[data-st=\"done\"] .badge{display:flex}\n.zz{position:absolute;z-index:5;left:58%;top:6px;font:700 13px var(--f-display);color:var(--muted);display:none}\n.wk[data-st=\"idle\"] .zz,.wk[data-st=\"none\"] .zz{display:block;animation:zz 3s ease-in-out infinite}\n.wk[data-st=\"idle\"] .av2,.wk[data-st=\"none\"] .av2{opacity:.72;animation:breathe 4s ease-in-out infinite}\n.wk[data-st=\"none\"] .av2{filter:grayscale(.8)}\n.wk[data-st=\"working\"] .av2{animation:type .55s ease-in-out infinite}\n.wk[data-st=\"working\"] .mon{animation:glow 1.4s ease-in-out infinite}\n.wk[data-st=\"working\"] .mon i{opacity:.9;animation:ln 1.1s steps(2) infinite}\n.wk[data-st=\"working\"] .mon i:nth-child(2){animation-delay:.3s}.wk[data-st=\"working\"] .mon i:nth-child(3){animation-delay:.6s}\n.wk[data-st=\"waiting_user\"] .av2{animation:hop 1s ease-in-out infinite}\n.wk[data-st=\"waiting_user\"] .bub{animation:pulseb 1.6s ease-in-out infinite}\n.wk[data-st=\"error\"] .av2{animation:shake .4s linear infinite}\n.wk[data-st=\"done\"] .av2{animation:hop 2.4s ease-in-out infinite}\n.wk:hover .tag{border-color:var(--c)}\n@keyframes type{0%,100%{transform:translateY(0)}50%{transform:translateY(-2px) rotate(-1.5deg)}}\n@keyframes hop{0%,100%{transform:translateY(0)}40%{transform:translateY(-9px)}}\n@keyframes shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-2px)}75%{transform:translateX(2px)}}\n@keyframes breathe{0%,100%{transform:scaleY(1)}50%{transform:scaleY(.97)}}\n@keyframes glow{0%,100%{box-shadow:0 0 0 0 transparent}50%{box-shadow:0 0 12px 2px var(--c)}}\n@keyframes ln{0%{width:8px}100%{width:28px}}\n@keyframes zz{0%,100%{transform:translateY(0);opacity:.4}50%{transform:translateY(-7px);opacity:1}}\n@keyframes pulseb{0%,100%{transform:scale(1)}50%{transform:scale(1.04)}}\n@media (prefers-reduced-motion:reduce){.wk *,.wk .av2,.wk .mon,.wk .bub{animation:none!important}}\n@media (max-width:420px){.floor{grid-template-columns:34px 1fr}.plate b{font-size:19px}.room{padding:8px 6px 0}}\n\n/* actividad */\n.feed{display:flex;flex-direction:column}\n.ev{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:baseline;padding:8px 0;border-bottom:1px solid var(--line)}\n.ev:last-child{border-bottom:0}\n.ev span:nth-child(2){min-width:0;overflow-wrap:anywhere}\n.ev .t{font:400 12px var(--f-mono);color:var(--muted);white-space:nowrap}\n\n/* leyenda */\n.legend{display:flex;flex-wrap:wrap;gap:6px 16px;font:400 12px var(--f-mono);color:var(--muted)}\n.legend span{display:flex;align-items:center;gap:6px}\n\n/* hoja de detalle */\n.sheet{position:fixed;inset:0;z-index:20;display:flex;align-items:flex-end;justify-content:center;background:color-mix(in srgb,var(--bg) 70%,transparent)}\n.sheet[hidden]{display:none}\n.sheet-card{width:100%;max-width:640px;max-height:86%;overflow:auto;background:var(--surface);border:1px solid var(--line);border-radius:14px 14px 0 0;padding:18px max(16px,env(safe-area-inset-left,0px)) calc(18px + env(safe-area-inset-bottom,0px));display:flex;flex-direction:column;gap:12px;box-shadow:0 -8px 30px rgba(0,0,0,.18)}\n.sheet-head{display:flex;gap:12px;align-items:center;justify-content:space-between}\n.sheet-head h3{font-size:22px}\n.sheet-card h4{margin:0;font:500 12px var(--f-mono);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\n.sheet-card ul{margin:0;padding-left:18px;display:flex;flex-direction:column;gap:4px;font-size:14px}\n.pform{display:flex;flex-direction:column;gap:8px;border-top:1px solid var(--line);padding-top:12px}\n.pform[hidden]{display:none}\nselect,input[type=text]{background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:9px 10px;width:100%}\n.err{color:var(--st-err);font-size:13px;margin:0}\n\n/* escena 3D */\n:root{--sky1:#8ec9ff;--sky2:#eaf5ff}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]){--sky1:#05070f;--sky2:#1b2347}}\n:root[data-theme=\"dark\"]{--sky1:#05070f;--sky2:#1b2347}\n.stage{padding:12px;gap:10px}\n.stage-bar{display:flex;flex-wrap:wrap;gap:8px 12px;align-items:center;justify-content:space-between}\n.stage-bar h2{font-size:19px}\n.btn.sm{padding:6px 12px;font-size:13px;font-weight:500}\n.cv{position:relative;height:clamp(480px,130vw,720px);border-radius:12px;overflow:hidden;background:linear-gradient(var(--sky1),var(--sky2))}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]) .cv{background:radial-gradient(1.5px 1.5px at 12% 18%,#fff8,transparent),radial-gradient(1.5px 1.5px at 70% 10%,#fff8,transparent),radial-gradient(1px 1px at 40% 30%,#fff8,transparent),radial-gradient(1.5px 1.5px at 88% 40%,#fff8,transparent),radial-gradient(1px 1px at 25% 55%,#fff6,transparent),linear-gradient(var(--sky1),var(--sky2))}}\n:root[data-theme=\"dark\"] .cv{background:radial-gradient(1.5px 1.5px at 12% 18%,#fff8,transparent),radial-gradient(1.5px 1.5px at 70% 10%,#fff8,transparent),radial-gradient(1px 1px at 40% 30%,#fff8,transparent),radial-gradient(1.5px 1.5px at 88% 40%,#fff8,transparent),linear-gradient(var(--sky1),var(--sky2))}\n.cv canvas{display:block;touch-action:pan-y;cursor:grab}\n.chips{display:flex;gap:6px;overflow-x:auto;padding-bottom:2px;scrollbar-width:thin}\n.chip3{all:unset;cursor:pointer;flex:none;white-space:nowrap;padding:7px 12px;border:1px solid var(--line);border-radius:999px;background:var(--surface2);font:500 13px var(--f-body)}\n.chip3:focus-visible{outline:2px solid var(--st-work);outline-offset:2px}\n.chip3[aria-pressed=\"true\"]{background:var(--btn);color:var(--btn-ink);border-color:var(--btn)}\n.chip3 b{font:500 11px var(--f-mono);opacity:.8}\n</style>\n\n<div class=\"wrap\" id=\"app\">\n  <header class=\"top\">\n    <div class=\"brand\">\n      <div class=\"kicker\">DEVISEBIT · Gabinete</div>\n      <h1>Oficina</h1>\n    </div>\n    <div class=\"counts\" id=\"counts\" aria-live=\"polite\"></div>\n  </header>\n  <div class=\"sync\" id=\"sync\">Conectando con la base…</div>\n\n  <section class=\"block\" id=\"attn\" aria-labelledby=\"attn-h\"></section>\n\n  <section class=\"block\" aria-labelledby=\"ord-h\">\n    <h2 id=\"ord-h\">Órdenes al jefe de gabinete</h2>\n    <p class=\"sub\">Escribilas una vez. El jefe las lee enseguida, propone qué agente hace cada cosa y te pide el OK acá. También podés dictarlas con el micrófono o mandarle un audio por WhatsApp.</p>\n    <div class=\"compose\">\n      <label for=\"ordtxt\" class=\"meta\">Nueva orden</label>\n      <textarea id=\"ordtxt\" placeholder=\"Ej.: Armá una propuesta para la licitación de PAMI y avisale a Bárbara que prepare la demo.\"></textarea>\n      <div class=\"row\">\n        <button class=\"btn\" id=\"ordsend\" type=\"button\">Enviar al gabinete</button>\n        <button class=\"btn ghost\" id=\"ordmic\" type=\"button\" aria-pressed=\"false\" hidden>Dictar con el micrófono</button>\n        <button class=\"btn\" id=\"ordcall\" type=\"button\" aria-pressed=\"false\" hidden>Llamar al jefe (voz)</button>\n        <span class=\"err\" id=\"orderr\" hidden></span>\n      </div>\n    </div>\n    <div class=\"orders\" id=\"orders\"></div>\n  </section>\n\n  <section class=\"block stage\" id=\"stage\" aria-label=\"Oficina en 3D\" hidden>\n    <div class=\"stage-bar\"><h2>Oficina en vivo</h2><button class=\"btn ghost sm\" id=\"viewtgl\" type=\"button\">Ver como lista</button></div>\n    <div class=\"chips only3d\" id=\"chips\" role=\"group\" aria-label=\"Elegir zona\"></div>\n    <div class=\"cv only3d\" id=\"cv\"></div>\n    <p class=\"sub only3d\">Elegí una zona para acercarte, arrastrá hacia los costados para girar y tocá a un agente para ver el detalle. Cuando alguien descansa, se va al café. Doble toque: volver a ver todo.</p>\n  </section>\n\n  <div id=\"floors\"></div>\n\n  <section class=\"block\" aria-labelledby=\"act-h\">\n    <h2 id=\"act-h\">Actividad reciente</h2>\n    <div class=\"feed\" id=\"feed\"></div>\n  </section>\n\n  <div class=\"legend\" id=\"legend\"></div>\n</div>\n\n<div class=\"sheet\" id=\"sheet\" hidden>\n  <div class=\"sheet-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"sh-title\">\n    <div class=\"sheet-head\">\n      <h3 id=\"sh-title\"></h3>\n      <button class=\"btn ghost\" id=\"shclose\" type=\"button\">Cerrar</button>\n    </div>\n    <div id=\"shbody\"></div>\n    <div class=\"pform\" id=\"pform\" hidden>\n      <h4>Actualizar su estado</h4>\n      <label class=\"meta\" for=\"pst\">Estado</label>\n      <select id=\"pst\">\n        <option value=\"working\">trabajando</option>\n        <option value=\"waiting_user\">te necesita</option>\n        <option value=\"done\">terminó</option>\n        <option value=\"idle\">en reposo</option>\n        <option value=\"error\">bloqueado</option>\n      </select>\n      <label class=\"meta\" for=\"pnom\">Nombre</label>\n      <div class=\"row\"><input type=\"text\" id=\"pnom\" maxlength=\"40\"><button class=\"btn ghost\" id=\"pnsave\" type=\"button\">Cambiar nombre</button></div>\n      <label class=\"meta\" for=\"ppaso\">En qué está (máx. 60 caracteres)</label>\n      <input type=\"text\" id=\"ppaso\" maxlength=\"60\" placeholder=\"Ej.: preparando la demo de WhatsApp\">\n      <div class=\"row\"><button class=\"btn\" id=\"psave\" type=\"button\">Guardar estado</button><span class=\"err\" id=\"perr\" hidden></span></div>\n    </div>\n  </div>\n</div>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"></script>\n<script>\nconst ST={\n  working:{t:'trabajando',c:'var(--st-work)'},\n  done:{t:'terminó',c:'var(--st-done)'},\n  idle:{t:'en reposo',c:'var(--st-idle)'},\n  waiting_user:{t:'te necesita',c:'var(--st-wait)'},\n  error:{t:'error',c:'var(--st-err)'},\n  none:{t:'sin reporte',c:'var(--st-idle)'}\n};\nconst OST={\n  nueva:{t:'espera al jefe',c:'var(--st-idle)'},\n  propuesta:{t:'para tu OK',c:'var(--st-wait)'},\n  aprobada:{t:'aprobada',c:'var(--st-work)'},\n  repartida:{t:'repartida',c:'var(--st-done)'},\n  rechazada:{t:'rechazada',c:'var(--st-idle)'},\n  hecha:{t:'hecha',c:'var(--st-done)'}\n};\nconst PISOS={5:'Dirección y gabinete',4:'Comercial y licitaciones',3:'Contenido y redes',2:'Administración y finanzas',1:'Sistemas y desarrollo',0:'Equipo'};\nconst CARGO={5:'Jefa de gabinete',4:'Responsable de Comercial',3:'Responsable de Contenido',2:'Responsable de Administración',1:'Responsable de Sistemas'};\nfunction respDe(p){ const r=S.agentes.find(a=>a.tipo==='persona'&&a.piso===p); return r?(CARGO[p]||'Responsable')+': '+r.nombre:(CARGO[p]||'Responsable')+': a definir'; }\nconst S={agentes:[],eventos:[],ordenes:[],tareas:[],got:{},db:null,user:null,canWrite:false,sel:null};\nconst $=id=>document.getElementById(id);\nconst esc=s=>String(s==null?'':s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n\nfunction ago(iso){\n  const t=Date.parse(iso); if(!t) return '';\n  const m=Math.max(0,Math.round((Date.now()-t)/60000));\n  if(m<1) return 'recién';\n  if(m<60) return 'hace '+m+' min';\n  const h=Math.round(m/60); if(h<24) return 'hace '+h+' h';\n  const d=Math.round(h/24); return 'hace '+d+' d';\n}\n\nfunction avatar(l){\n  l=l||{}; const c=l.color||'#959595', f=l.forma||'sphere', a=l.acc||'none';\n  const dark=/^#?(0{6}|1[0-9a-f]{5})$/i.test(c.replace('#',''));\n  const eye=dark?'#fff':'#111';\n  let b='';\n  if(f==='rsquare') b='<rect x=\"10\" y=\"12\" width=\"44\" height=\"44\" rx=\"13\" fill=\"'+c+'\"/>';\n  else if(f==='star') b='<polygon points=\"32,6 39,24 58,26 43,39 48,58 32,48 16,58 21,39 6,26 25,24\" fill=\"'+c+'\" stroke=\"'+c+'\" stroke-width=\"3\" stroke-linejoin=\"round\"/>';\n  else if(f==='hexagon') b='<polygon points=\"32,8 54,20 54,46 32,58 10,46 10,20\" fill=\"'+c+'\" stroke=\"'+c+'\" stroke-width=\"3\" stroke-linejoin=\"round\"/>';\n  else if(f==='triangle') b='<polygon points=\"32,9 57,55 7,55\" fill=\"'+c+'\" stroke=\"'+c+'\" stroke-width=\"4\" stroke-linejoin=\"round\"/>';\n  else if(f==='pill') b='<rect x=\"17\" y=\"6\" width=\"30\" height=\"52\" rx=\"15\" fill=\"'+c+'\"/>';\n  else if(f==='drop') b='<path d=\"M32 6C45 22 53 33 53 43a21 21 0 0 1-42 0C11 33 19 22 32 6Z\" fill=\"'+c+'\"/>';\n  else if(f==='flower') b='<g fill=\"'+c+'\"><circle cx=\"32\" cy=\"17\" r=\"12\"/><circle cx=\"32\" cy=\"47\" r=\"12\"/><circle cx=\"17\" cy=\"32\" r=\"12\"/><circle cx=\"47\" cy=\"32\" r=\"12\"/><circle cx=\"32\" cy=\"32\" r=\"14\"/></g>';\n  else if(f==='cloud') b='<g fill=\"'+c+'\"><circle cx=\"21\" cy=\"38\" r=\"13\"/><circle cx=\"34\" cy=\"29\" r=\"15\"/><circle cx=\"46\" cy=\"39\" r=\"12\"/><rect x=\"21\" y=\"38\" width=\"25\" height=\"13\"/></g>';\n  else b='<circle cx=\"32\" cy=\"33\" r=\"23\" fill=\"'+c+'\"/>';\n  let face='<circle cx=\"25\" cy=\"34\" r=\"2.6\" fill=\"'+eye+'\"/><circle cx=\"39\" cy=\"34\" r=\"2.6\" fill=\"'+eye+'\"/>';\n  let acc='';\n  if(a==='glasses'){ face=''; acc='<g fill=\"none\" stroke=\"'+eye+'\" stroke-width=\"2.6\"><circle cx=\"24\" cy=\"34\" r=\"6.5\"/><circle cx=\"40\" cy=\"34\" r=\"6.5\"/><line x1=\"30.5\" y1=\"34\" x2=\"33.5\" y2=\"34\"/></g>'; }\n  else if(a==='antenna') acc='<line x1=\"32\" y1=\"9\" x2=\"32\" y2=\"2\" stroke=\"'+eye+'\" stroke-width=\"2.4\"/><circle cx=\"32\" cy=\"3\" r=\"3\" fill=\"'+eye+'\"/>';\n  else if(a==='bow') acc='<g fill=\"'+eye+'\"><polygon points=\"32,52 21,46 21,58\"/><polygon points=\"32,52 43,46 43,58\"/></g>';\n  else if(a==='stem') acc='<path d=\"M32 10C32 4 38 2 42 3C41 8 37 11 32 10Z\" fill=\"'+eye+'\"/>';\n  return '<svg viewBox=\"0 0 64 64\" aria-hidden=\"true\">'+b+face+acc+'</svg>';\n}\n\n/* estado más reciente de cada agente */\nfunction latest(){\n  const m={};\n  for(const e of S.eventos){ const k=e.agente; if(k && !m[k]) m[k]=e; } // eventos vienen del más nuevo al más viejo\n  return m;\n}\nfunction stateOf(ag,lat){\n  const e=lat[ag.id];\n  if(!e) return {k:'none',paso:'',at:''};\n  const k=ST[e.estado]?e.estado:'none';\n  return {k,paso:e.paso||'',at:e.at||''};\n}\nfunction tareasDe(id){ return S.tareas.filter(t=>t.agente===id && t.estado!=='hecha'); }\nfunction nombreAg(id){ const a=S.agentes.find(x=>x.id===id); return a?a.nombre:id; }\n\nfunction renderCounts(lat){\n  const c={working:0,waiting_user:0,error:0,rest:0};\n  for(const a of S.agentes){ const k=stateOf(a,lat).k; if(k==='working')c.working++; else if(k==='waiting_user')c.waiting_user++; else if(k==='error')c.error++; else c.rest++; }\n  const p=(n,l,col)=>'<div class=\"pill\"><span class=\"dot\" style=\"--c:'+col+'\"></span><b>'+n+'</b> '+l+'</div>';\n  $('counts').innerHTML=p(c.working,'trabajando',ST.working.c)+p(c.waiting_user,'te necesitan',ST.waiting_user.c)+p(c.error,'errores',ST.error.c)+p(c.rest,'en reposo',ST.idle.c);\n}\n\nfunction renderAttn(lat){\n  const items=[];\n  for(const a of S.agentes){\n    const s=stateOf(a,lat);\n    if(s.k==='waiting_user'||s.k==='error') items.push('<div class=\"attn-item\"><span class=\"dot\" style=\"--c:'+ST[s.k].c+'\"></span><p><b>'+esc(a.nombre)+'</b>: '+esc(s.paso||ST[s.k].t)+'<small>'+ST[s.k].t+' · '+ago(s.at)+'</small></p></div>');\n  }\n  for(const o of S.ordenes){\n    if(o.estado==='propuesta') items.push('<div class=\"attn-item\"><span class=\"dot\" style=\"--c:'+OST.propuesta.c+'\"></span><p>Propuesta del jefe para aprobar: <b>'+esc(String(o.texto||'').slice(0,90))+'</b><small>abajo, en Órdenes</small></p></div>');\n  }\n  $('attn').classList.toggle('attn',items.length>0);\n  $('attn').innerHTML='<h2 id=\"attn-h\">'+(items.length?'Necesita de vos':'Nada espera tu decisión')+'</h2>'+\n    (items.length?'<div class=\"attn-list\">'+items.join('')+'</div>':'<p class=\"calm\">Cuando un agente te necesite o falle algo, aparece acá arriba.</p>');\n}\n\nfunction renderOrders(){\n  const box=$('orders');\n  if(!S.ordenes.length){ box.innerHTML='<p class=\"calm\">Todavía no diste ninguna orden.</p>'; return; }\n  box.innerHTML=S.ordenes.slice(0,12).map(o=>{\n    const st=OST[o.estado]||OST.nueva;\n    let extra='';\n    if(o.resumen) extra+='<p class=\"sub\">'+esc(o.resumen)+'</p>';\n    if(Array.isArray(o.reparto)&&o.reparto.length) extra+='<ul class=\"reparto\">'+o.reparto.map(r=>'<li><b>'+esc(nombreAg(r.agente))+'</b>: '+esc(r.tarea)+'</li>').join('')+'</ul>';\n    let acts='';\n    if(o.estado==='propuesta'&&S.canWrite) acts='<div class=\"row\"><button class=\"btn\" data-ap=\"'+esc(o.id)+'\" type=\"button\">Aprobar</button><button class=\"btn ghost\" data-rj=\"'+esc(o.id)+'\" type=\"button\">Rechazar</button></div>';\n    return '<div class=\"order\"><span class=\"chip\" style=\"--c:'+st.c+'\">'+st.t+'</span><p>'+esc(o.texto)+'</p>'+extra+acts+'<span class=\"meta\">'+esc(o.por||'')+' · '+ago(o.creado)+'</span></div>';\n  }).join('');\n}\n\nfunction deskHTML(a,lat){\n  const s=stateOf(a,lat), st=ST[s.k], tk=tareasDe(a.id).length;\n  const idleTxt=(s.k==='none')?'Todavía no reportó':(s.k==='idle'?'Descansando':'');\n  const txt=s.paso||idleTxt||(a.rol||'');\n  const mark={waiting_user:'!',error:'×',done:'✓'}[s.k]||'';\n  return '<button class=\"desk wk\" type=\"button\" data-id=\"'+esc(a.id)+'\" data-st=\"'+s.k+'\" style=\"--c:'+st.c+'\" aria-label=\"'+esc(a.nombre+', '+st.t)+'\">'+\n    '<div class=\"bub\"><span>'+esc(txt)+'</span></div>'+\n    '<div class=\"who\"><span class=\"zz\">z z</span><span class=\"badge\">'+mark+'</span>'+\n      '<div class=\"av2\">'+avatar(a.look)+'</div>'+\n      '<div class=\"mon\"><i></i><i></i><i></i></div>'+\n      '<div class=\"dk\"><div class=\"top\"></div><div class=\"leg\"></div></div></div>'+\n    '<div class=\"tag\"><b>'+esc(a.nombre)+'</b><small>'+st.t+(tk?' · '+tk+' tarea'+(tk>1?'s':''):'')+'</small></div></button>';\n}\n\nfunction renderFloors(lat){\n  if(!S.agentes.length){ $('floors').innerHTML=S.got.agentes?'<div class=\"block\"><p class=\"calm\">Todavía no hay agentes cargados en la oficina.</p></div>':''; return; }\n  const byP={};\n  for(const a of S.agentes){ (byP[a.piso]=byP[a.piso]||[]).push(a); }\n  const pisos=Object.keys(byP).map(Number).sort((x,y)=>y-x);\n  $('floors').innerHTML='<div class=\"building\">'+pisos.map(p=>{\n    const list=byP[p].sort((x,y)=>(x.orden||0)-(y.orden||0));\n    const w=list.filter(a=>stateOf(a,lat).k==='working').length;\n    return '<section class=\"floor\" aria-label=\"'+esc(PISOS[p]||('Piso '+p))+'\"><div class=\"plate\"><span>'+(p===0?'PB':'PISO')+'</span>'+(p===0?'':'<b>'+p+'</b>')+'</div><div class=\"room\"><div class=\"rhead\"><h2>'+esc(PISOS[p]||list[0].equipo||'')+'</h2><span class=\"fc\">'+esc(respDe(p))+' · '+w+' de '+list.length+' trabajando</span></div><div class=\"desks\">'+list.map(a=>deskHTML(a,lat)).join('')+'</div></div></section>';\n  }).join('')+'</div>';\n}\n\nfunction renderFeed(){\n  const ev=S.eventos.slice(0,12);\n  $('feed').innerHTML=ev.length?ev.map(e=>{\n    const st=ST[e.estado]||ST.none;\n    return '<div class=\"ev\"><span class=\"dot\" style=\"--c:'+st.c+'\"></span><span><b>'+esc(nombreAg(e.agente))+'</b> · '+esc(e.paso||st.t)+'</span><span class=\"t\">'+ago(e.at)+'</span></div>';\n  }).join(''):'<p class=\"calm\">Todavía no hay movimientos. Aparecen cuando los agentes empiecen a reportar.</p>';\n}\n\nfunction renderSheet(){\n  if(!S.sel) return;\n  const a=S.agentes.find(x=>x.id===S.sel); if(!a) return;\n  const lat=latest(), s=stateOf(a,lat), st=ST[s.k];\n  $('sh-title').textContent=a.nombre;\n  const hist=S.eventos.filter(e=>e.agente===a.id).slice(0,6);\n  const tk=tareasDe(a.id);\n  $('shbody').innerHTML=\n    '<p class=\"sub\">'+esc(a.rol||'')+'</p>'+\n    '<div class=\"row\"><span class=\"chip\" style=\"--c:'+st.c+'\">'+st.t+'</span><span class=\"meta\">'+(s.at?ago(s.at):'sin reportes todavía')+'</span></div>'+\n    (s.paso?'<p style=\"margin:0;overflow-wrap:anywhere\">'+esc(s.paso)+'</p>':'')+\n    (a.nohace?'<h4>Lo que no hace</h4><p class=\"meta\" style=\"margin:0\">'+esc(a.nohace)+'</p>':'')+\n    (a.horario?'<h4>Cuándo corre</h4><p class=\"meta\" style=\"margin:0\">'+esc(a.horario)+'</p>':'')+\n    '<h4>Tareas que le dio el gabinete</h4>'+(tk.length?'<ul>'+tk.map(t=>'<li>'+esc(t.texto)+'</li>').join('')+'</ul>':'<p class=\"calm\">Ninguna pendiente.</p>')+\n    '<h4>Últimos movimientos</h4>'+(hist.length?'<ul>'+hist.map(e=>'<li>'+esc(e.paso||(ST[e.estado]||ST.none).t)+' <span class=\"meta\">· '+ago(e.at)+'</span></li>').join('')+'</ul>':'<p class=\"calm\">Sin movimientos.</p>');\n  const isP=a.tipo==='persona';\n  $('pform').hidden=!(isP&&S.canWrite);\n  if(isP && $('pnom').dataset.for!==a.id && document.activeElement!==$('pnom')){ $('pnom').value=a.nombre||''; $('pnom').dataset.for=a.id; }\n}\n\nfunction renderAll(){\n  const lat=latest();\n  renderCounts(lat); renderAttn(lat); renderOrders(); renderFloors(lat); renderFeed(); renderSheet();\n  if(window.sync3D) window.sync3D(lat);\n  $('legend').innerHTML=['working','waiting_user','done','idle','error'].map(k=>'<span><i class=\"dot\" style=\"--c:'+ST[k].c+'\"></i>'+ST[k].t+'</span>').join('');\n}\nlet pend=false;\nfunction schedule(){ if(pend) return; pend=true; requestAnimationFrame(()=>{pend=false; renderAll();}); }\n\n/* acciones */\ndocument.addEventListener('click',async ev=>{\n  const t=ev.target.closest('button'); if(!t) return;\n  if(t.classList.contains('desk')){ S.sel=t.dataset.id; $('sheet').hidden=false; renderSheet(); return; }\n  if(t.id==='shclose'){ S.sel=null; $('sheet').hidden=true; return; }\n  if(t.dataset.ap||t.dataset.rj){\n    const id=t.dataset.ap||t.dataset.rj;\n    try{ await S.db.doc('ordenes/'+id).update({estado:t.dataset.ap?'aprobada':'rechazada',decidida:new Date().toISOString()}); }\n    catch(e){ $('orderr').hidden=false; $('orderr').textContent='No se pudo guardar. Probá de nuevo.'; }\n  }\n});\n$('sheet').addEventListener('click',e=>{ if(e.target===$('sheet')){ S.sel=null; $('sheet').hidden=true; } });\ndocument.addEventListener('keydown',e=>{ if(e.key==='Escape'&&!$('sheet').hidden){ S.sel=null; $('sheet').hidden=true; } });\n\n$('ordsend').addEventListener('click',async()=>{\n  const txt=$('ordtxt').value.trim(), er=$('orderr'); er.hidden=true;\n  if(!txt) return;\n  if(!S.db||!S.canWrite){ er.hidden=false; er.textContent='Tu usuario no puede escribir en la oficina.'; return; }\n  $('ordsend').disabled=true;\n  try{\n    await S.db.collection('ordenes').add({texto:txt.slice(0,1500),estado:'nueva',creado:new Date().toISOString(),por:(S.user&&S.user.isOwner&&S.user.isOwner())?'Julio':'equipo'});\n    $('ordtxt').value='';\n  }catch(e){ er.hidden=false; er.textContent='No se pudo enviar. Probá de nuevo.'; }\n  $('ordsend').disabled=false;\n});\n$('psave').addEventListener('click',async()=>{\n  const er=$('perr'); er.hidden=true;\n  if(!S.db||!S.sel) return;\n  $('psave').disabled=true;\n  try{\n    await S.db.collection('eventos').add({agente:S.sel,estado:$('pst').value,paso:$('ppaso').value.trim().slice(0,60),at:new Date().toISOString(),por:'panel'});\n    $('ppaso').value='';\n  }catch(e){ er.hidden=false; er.textContent='No se pudo guardar. Probá de nuevo.'; }\n  $('psave').disabled=false;\n});\n\n/* conexión */\nfunction sub(name,query,key){\n  let first=true;\n  return query.onSnapshot(snap=>{\n    S[key]=snap.docs.map(d=>Object.assign({id:d.id},d.data()));\n    S.got[key]=true;\n    if(!snap.metadata.fromCache) { $('sync').textContent='En vivo · actualizado '+new Date().toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'}); $('sync').dataset.bad=''; clearTimeout(S.timer); }\n    schedule();\n  },err=>{\n    $('sync').textContent='No se pudo leer «'+name+'» ('+(err&&err.code||'error')+').'; $('sync').dataset.bad='1';\n  });\n}\nasync function start(){\n  renderAll();\n  S.timer=setTimeout(()=>{ $('sync').textContent='Todavía no hay respuesta de la base; los datos pueden estar desactualizados.'; $('sync').dataset.bad='1'; },10000);\n  try{\n    S.user=await window.claude.use('user');\n    S.db=await window.claude.use('db');\n  }catch(e){}\n  if(!S.db){ clearTimeout(S.timer); $('sync').textContent='Sin conexión con la base.'; $('sync').dataset.bad='1'; $('ordsend').disabled=true; return; }\n  try{ const cw=S.user&&S.user.can?S.user.can('data.write'):null; S.canWrite=cw!==false; }catch(e){ S.canWrite=true; }\n  sub('agentes',S.db.collection('agentes'),'agentes');\n  sub('eventos',S.db.collection('eventos').orderBy('at','desc').limit(400),'eventos');\n  sub('órdenes',S.db.collection('ordenes').orderBy('creado','desc').limit(30),'ordenes');\n  sub('tareas',S.db.collection('tareas').limit(300),'tareas');\n  setInterval(schedule,60000);\n}\nstart();\n</script>\n<script>\n(function(){\n'use strict';\nconst stage=document.getElementById('stage'), cv=document.getElementById('cv'), chips=document.getElementById('chips'), tgl=document.getElementById('viewtgl'), flo=document.getElementById('floors');\nlet ok=false;\ntry{ if(window.THREE){ const c=document.createElement('canvas'); ok=!!(c.getContext('webgl')||c.getContext('experimental-webgl')); } }catch(e){}\nif(!ok){ stage.hidden=true; return; }\nconst T=window.THREE;\nlet renderer;\ntry{ renderer=new T.WebGLRenderer({antialias:true,alpha:true}); }catch(e){ stage.hidden=true; return; }\nrenderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));\nrenderer.shadowMap.enabled=true; renderer.shadowMap.type=T.PCFSoftShadowMap;\ncv.appendChild(renderer.domElement);\nrenderer.domElement.setAttribute('aria-label','Oficina en 3D');\n\nconst reduce=matchMedia('(prefers-reduced-motion: reduce)').matches, M=reduce?0.2:1;\nconst isDark=()=>{ const r=document.documentElement.dataset.theme; if(r==='dark') return true; if(r==='light') return false; return matchMedia('(prefers-color-scheme: dark)').matches; };\nfunction pal(){ return isDark()\n  ? {wall:0x2b3350,wall2:0x39426a,floor:0x5a4a3a,slab:0x1b1f2a,desk:0x7a5c3e,deskTop:0x9a764f,glass:0x3b7bd1,ground:0x141a24,tree:0x1f7a52,cloud:0x56618a,cloudOp:.55,bub:'#1f2330',ink:'#eceef2',hemi:0.75,sun:0.55,hemiG:0x222a40,star:true}\n  : {wall:0xe9edf5,wall2:0xd3d9e6,floor:0xcdb590,slab:0xaeb4c2,desk:0x9b7650,deskTop:0xbc9362,glass:0x9fd0ff,ground:0x86b873,tree:0x3fa66a,cloud:0xffffff,cloudOp:.92,bub:'#ffffff',ink:'#15171c',hemi:0.72,sun:0.45,hemiG:0xaab4c4,star:false}; }\nlet P=pal();\nconst cssCol=v=>{ const s=getComputedStyle(document.documentElement).getPropertyValue(v).trim()||'#8a919e'; return s; };\nfunction stCols(){ return {working:cssCol('--st-work'),done:cssCol('--st-done'),waiting_user:cssCol('--st-wait'),error:cssCol('--st-err'),idle:cssCol('--st-idle'),none:cssCol('--st-idle')}; }\nlet SC=stCols();\nconst STT={working:'TRABAJANDO',done:'TERMINÓ',waiting_user:'TE NECESITA',error:'ERROR',idle:'EN REPOSO',none:'SIN REPORTE'};\n\nconst scene=new T.Scene();\nconst cam=new T.PerspectiveCamera(36,1,0.5,300);\nconst hemi=new T.HemisphereLight(0xffffff,0x8899aa,1); scene.add(hemi);\nconst sun=new T.DirectionalLight(0xffffff,0.85); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.bias=-0.0006; scene.add(sun); scene.add(sun.target);\nlet root=null, ents=new Map(), levels=[], ranges={}, W=10, H=3.8, D=5.2, totalH=10, clouds=[], motes=null, beacon=null;\n\n/* ---------- helpers de lienzo ---------- */\nfunction rr(x,a,b,w,h,r){ x.beginPath(); x.moveTo(a+r,b); x.arcTo(a+w,b,a+w,b+h,r); x.arcTo(a+w,b+h,a,b+h,r); x.arcTo(a,b+h,a,b,r); x.arcTo(a,b,a+w,b,r); x.closePath(); }\nfunction sprite(w,h,sw,sh){\n  const c=document.createElement('canvas'); c.width=w; c.height=h;\n  const tex=new T.CanvasTexture(c); tex.anisotropy=4;\n  const sp=new T.Sprite(new T.SpriteMaterial({map:tex,transparent:true,depthTest:false}));\n  sp.scale.set(sw,sh,1); sp.renderOrder=10;\n  sp.userData.c=c; sp.userData.x=c.getContext('2d'); sp.userData.tex=tex; return sp;\n}\nfunction wrap(x,text,maxW,maxL){\n  const words=String(text).split(/\\s+/), lines=[]; let cur='';\n  for(const w of words){ const t=cur?cur+' '+w:w; if(x.measureText(t).width>maxW && cur){ lines.push(cur); cur=w; } else cur=t; }\n  if(cur) lines.push(cur);\n  if(lines.length>maxL){ lines.length=maxL; let l=lines[maxL-1]; while(x.measureText(l+'…').width>maxW && l.length>1) l=l.slice(0,-1); lines[maxL-1]=l+'…'; }\n  return lines;\n}\nfunction makeBubble(){\n  const sp=sprite(640,224,2.5,0.875); let last='';\n  sp.userData.set=(text,col)=>{\n    const key=text+'|'+col+'|'+P.bub; if(key===last) return; last=key;\n    const x=sp.userData.x, Wc=640, Hc=224; x.clearRect(0,0,Wc,Hc);\n    rr(x,6,6,Wc-12,Hc-52,34); x.fillStyle=P.bub; x.fill(); x.lineWidth=7; x.strokeStyle=col; x.stroke();\n    x.beginPath(); x.moveTo(Wc/2-24,Hc-48); x.lineTo(Wc/2,Hc-6); x.lineTo(Wc/2+24,Hc-48); x.fillStyle=P.bub; x.fill();\n    x.beginPath(); x.moveTo(Wc/2-24,Hc-47); x.lineTo(Wc/2,Hc-6); x.lineTo(Wc/2+24,Hc-47); x.stroke();\n    x.fillStyle=P.ink; x.font='600 40px Helvetica,Arial,sans-serif'; x.textAlign='center'; x.textBaseline='middle';\n    const lines=wrap(x,text,Wc-70,3), lh=48, y0=6+(Hc-52)/2-(lines.length-1)*lh/2;\n    lines.forEach((l,i)=>x.fillText(l,Wc/2,y0+i*lh));\n    sp.userData.tex.needsUpdate=true;\n  };\n  return sp;\n}\nfunction makeName(){\n  const sp=sprite(448,128,1.9,0.543); let last='';\n  sp.userData.set=(name,state,col)=>{\n    const key=name+'|'+state+'|'+col+'|'+P.bub; if(key===last) return; last=key;\n    const x=sp.userData.x; x.clearRect(0,0,448,128);\n    rr(x,4,4,440,108,22); x.fillStyle=P.bub; x.fill(); x.fillStyle=col; rr(x,4,96,440,20,10); x.fill();\n    x.fillStyle=P.bub; x.fillRect(4,88,440,10);\n    x.fillStyle=P.ink; x.font='700 44px Helvetica,Arial,sans-serif'; x.textAlign='center'; x.textBaseline='middle';\n    let n=name; while(x.measureText(n).width>410 && n.length>2) n=n.slice(0,-1); if(n!==name) n+='…';\n    x.fillText(n,224,40);\n    x.fillStyle=col; x.font='700 26px Helvetica,Arial,sans-serif'; x.fillText(state,224,78);\n    sp.userData.tex.needsUpdate=true;\n  };\n  return sp;\n}\nfunction makeSign(text){\n  const sp=sprite(640,96,3.4,0.51); const x=sp.userData.x;\n  rr(x,2,2,636,92,18); x.fillStyle='rgba(20,22,30,.9)'; x.fill();\n  x.fillStyle='#fff'; x.font='700 44px Helvetica,Arial,sans-serif'; x.textAlign='left'; x.textBaseline='middle';\n  let n=text; while(x.measureText(n).width>590 && n.length>2) n=n.slice(0,-1);\n  x.fillText(n,26,50); sp.userData.tex.needsUpdate=true; sp.material.depthTest=true; return sp;\n}\nfunction makeBadge(){ return sprite(128,128,0.62,0.62); }\nfunction drawBadge(sp,col,glyph){\n  const x=sp.userData.x; x.clearRect(0,0,128,128);\n  x.beginPath(); x.arc(64,64,58,0,7); x.fillStyle=col; x.fill(); x.lineWidth=8; x.strokeStyle='#fff'; x.stroke();\n  x.fillStyle='#fff'; x.font='800 76px Helvetica,Arial,sans-serif'; x.textAlign='center'; x.textBaseline='middle'; x.fillText(glyph,64,70);\n  sp.userData.tex.needsUpdate=true;\n}\nfunction makeZ(){\n  const sp=sprite(96,96,0.42,0.42); const x=sp.userData.x;\n  x.fillStyle=isDark()?'#cfd6e6':'#5a616e'; x.font='800 74px Helvetica,Arial,sans-serif'; x.textAlign='center'; x.textBaseline='middle'; x.fillText('z',48,52);\n  sp.userData.tex.needsUpdate=true; return sp;\n}\n\n/* ---------- personajes ---------- */\nconst EYEZ={sphere:.5,rsquare:.41,star:.55,hexagon:.5,triangle:.3,pill:.42,drop:.5,flower:.43,cloud:.45};\nconst EYEY={triangle:-.2};\nconst TOPY={sphere:.55,rsquare:.48,star:.62,hexagon:.48,triangle:.58,pill:.72,drop:.95,flower:.7,cloud:.5};\nfunction makeBody(look){\n  look=look||{}; const f=EYEZ[look.forma]?look.forma:'sphere', col=look.color||'#959595', acc=look.acc||'none';\n  const g=new T.Group(), inner=new T.Group(); g.add(inner);\n  const mat=new T.MeshStandardMaterial({color:col,roughness:.5,metalness:.05});\n  const add=(geo,x,y,z)=>{ const m=new T.Mesh(geo,mat); m.position.set(x||0,y||0,z||0); m.castShadow=true; inner.add(m); return m; };\n  switch(f){\n    case 'rsquare': add(new T.BoxGeometry(.95,.95,.8)); break;\n    case 'star': add(new T.DodecahedronGeometry(.62)); break;\n    case 'hexagon': add(new T.CylinderGeometry(.55,.55,.95,6)); break;\n    case 'triangle': add(new T.ConeGeometry(.68,1.15,3)).rotation.y=Math.PI; break;\n    case 'pill': add(new T.CylinderGeometry(.42,.42,.6,24)); add(new T.SphereGeometry(.42,24,16),0,.3,0); add(new T.SphereGeometry(.42,24,16),0,-.3,0); break;\n    case 'drop': add(new T.SphereGeometry(.52,24,16)).scale.set(1,1.1,1); add(new T.ConeGeometry(.32,.5,18),0,.68,0); break;\n    case 'flower': add(new T.SphereGeometry(.42,20,14)); for(let i=0;i<5;i++){ const a=i/5*Math.PI*2; add(new T.SphereGeometry(.26,14,10),Math.cos(a)*.5,Math.sin(a)*.5,0); } break;\n    case 'cloud': add(new T.SphereGeometry(.38,18,12),-.32,-.1,0); add(new T.SphereGeometry(.46,18,12),0,.1,0); add(new T.SphereGeometry(.36,18,12),.34,-.08,0); break;\n    default: add(new T.SphereGeometry(.55,28,20));\n  }\n  const dark=/^#?(0{6}|1[0-9a-f]{5})$/i.test(String(col).replace('#','')); const ecol=dark?0xffffff:0x111111;\n  const em=new T.MeshBasicMaterial({color:ecol}), eyes=new T.Group(), ez=EYEZ[f], ey=EYEY[f]||.06;\n  if(acc!=='glasses'){ for(const s of [-1,1]){ const e=new T.Mesh(new T.SphereGeometry(.075,12,10),em); e.position.set(s*.18,0,0); eyes.add(e); } }\n  else { for(const s of [-1,1]){ const e=new T.Mesh(new T.SphereGeometry(.05,10,8),em); e.position.set(s*.18,0,0); eyes.add(e); const r=new T.Mesh(new T.TorusGeometry(.13,.02,8,24),em); r.position.set(s*.18,0,.01); eyes.add(r); } const br=new T.Mesh(new T.BoxGeometry(.1,.02,.02),em); eyes.add(br); }\n  eyes.position.set(0,ey,ez); inner.add(eyes);\n  const ty=TOPY[f];\n  if(acc==='antenna'){ const c=new T.Mesh(new T.CylinderGeometry(.02,.02,.36,8),em); c.position.set(0,ty+.15,0); inner.add(c); const b=new T.Mesh(new T.SphereGeometry(.07,12,10),new T.MeshBasicMaterial({color:0xff4d5e})); b.position.set(0,ty+.35,0); inner.add(b); }\n  else if(acc==='bow'){ const bm=new T.MeshStandardMaterial({color:0xd7263d}); for(const s of [-1,1]){ const c=new T.Mesh(new T.ConeGeometry(.12,.22,12),bm); c.position.set(s*.13,-.38,ez-.02); c.rotation.z=-s*Math.PI/2; inner.add(c);} }\n  else if(acc==='stem'){ const c=new T.Mesh(new T.CylinderGeometry(.03,.04,.22,8),new T.MeshStandardMaterial({color:0x2d7a3e})); c.position.set(0,ty+.08,0); c.rotation.z=.3; inner.add(c); const lf=new T.Mesh(new T.SphereGeometry(.1,10,8),new T.MeshStandardMaterial({color:0x3fa66a})); lf.scale.set(1.6,.5,1); lf.position.set(.14,ty+.2,0); inner.add(lf); }\n  g.userData={mat,eyes,inner,base:new T.Color(col)};\n  return g;\n}\n\n/* ---------- campus: una planta con zonas de trabajo ---------- */\nfunction std(c,o){ return new T.MeshStandardMaterial(Object.assign({color:c,roughness:.8},o||{})); }\nfunction box(w,h,d,mat,x,y,z,sh){ const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat); m.position.set(x,y,z); if(sh!==false){m.castShadow=true;m.receiveShadow=true;} return m; }\nfunction disposeRoot(){\n  if(!root) return;\n  root.traverse(o=>{ if(o.geometry) o.geometry.dispose(); if(o.material){ const ms=Array.isArray(o.material)?o.material:[o.material]; ms.forEach(m=>{ if(m.map) m.map.dispose(); m.dispose(); }); } });\n  scene.remove(root); root=null;\n}\nfunction makeLabel(){\n  const sp=sprite(640,96,3.6,.54); let last='';\n  sp.userData.set=(text,sub,col)=>{\n    const key=text+'|'+sub+'|'+col; if(key===last) return; last=key;\n    const x=sp.userData.x; x.clearRect(0,0,640,96);\n    rr(x,2,2,636,92,20); x.fillStyle='rgba(18,20,28,.92)'; x.fill();\n    x.fillStyle=col; x.beginPath(); x.arc(40,48,14,0,7); x.fill();\n    x.fillStyle='#fff'; x.font='700 40px Helvetica,Arial,sans-serif'; x.textAlign='left'; x.textBaseline='middle';\n    let n=text.toUpperCase(); while(x.measureText(n).width>360 && n.length>2) n=n.slice(0,-1);\n    x.fillText(n,68,50);\n    x.fillStyle='#b8c0d0'; x.font='600 28px Helvetica,Arial,sans-serif'; x.textAlign='right'; x.fillText(sub,616,52);\n    sp.userData.tex.needsUpdate=true;\n  };\n  return sp;\n}\nconst ZCOL=['#cfe6ff','#ffe2cc','#dcf4d4','#f1d9ff','#fff0b8','#d3f2ee','#ffd6df'];\nconst SLOT=2.8, ROW=3.4, GAPX=1.2, GAPZ=2.4, WMAX=34;\nlet zones={}, spots=[], corrX=0, cafeAisle=0, meetScr=null, holo=null, ball=null, pong=null, floorRect={x0:-20,x1:20,z0:-2,z1:20};\nlet hitList=[], focusK=null, cur={tx:0,tz:8,dist:40,yaw:0}, tgt={tx:0,tz:8,dist:40}, yawOff=0;\n\nfunction layout(){\n  const byP={}; for(const a of S.agentes){ (byP[a.piso]=byP[a.piso]||[]).push(a); }\n  const pisos=Object.keys(byP).map(Number).sort((a,b)=>b-a), zs=[];\n  pisos.forEach((p,i)=>{\n    const list=byP[p].sort((x,y)=>(x.orden||0)-(y.orden||0)), n=list.length;\n    const cols=n<=3?Math.max(2,n):(n===4?2:3), rows=Math.ceil(n/cols);\n    zs.push({key:String(p),kind:'team',piso:p,name:PISOS[p]||(list[0]&&list[0].equipo)||('Piso '+p),list,cols,rows,w:cols*SLOT+1.4,d:rows*ROW+1.9});\n    if(i===0) zs.push({key:'meet',kind:'meet',name:'Sala de reuniones',list:[],w:9,d:7});\n  });\n  if(!zs.find(z=>z.key==='meet')) zs.push({key:'meet',kind:'meet',name:'Sala de reuniones',list:[],w:9,d:7});\n  zs.push({key:'cafe',kind:'cafe',name:'Café y descanso',list:[],w:13,d:8.4});\n  const bands=[]; let cu=[],x=0,h=0;\n  for(const z of zs){ if(x+z.w>WMAX&&cu.length){ bands.push({items:cu,h,w:x-GAPX}); cu=[]; x=0; h=0; } z.bx=x; cu.push(z); x+=z.w+GAPX; h=Math.max(h,z.d); }\n  bands.push({items:cu,h,w:x-GAPX});\n  const Wt=Math.max(...bands.map(b=>b.w)); let zc=0;\n  bands.forEach(b=>{ b.z0=zc; b.aisle=zc+b.h+GAPZ/2; b.items.forEach(z=>{ z.x0=z.bx-Wt/2; z.z0=b.z0; z.d=b.h; z.cx=z.x0+z.w/2; z.cz=z.z0+z.d/2; }); zc+=b.h+GAPZ; });\n  const last=bands[bands.length-1];\n  floorRect={x0:-Wt/2-3,x1:Wt/2+1.4,z0:-1.4,z1:zc-GAPZ+2.6};\n  corrX=-Wt/2-1.6; cafeAisle=bands.find(b=>b.items.find(z=>z.key==='cafe')).aisle;\n  return {zs,bands};\n}\n\nfunction build(){\n  disposeRoot(); ents=new Map(); zones={}; hitList=[]; clouds=[]; P=pal(); SC=stCols(); spots=[];\n  hemi.groundColor.set(P.hemiG); hemi.intensity=P.hemi; sun.intensity=P.sun;\n  root=new T.Group(); scene.add(root);\n  const {zs,bands}=layout();\n  const dk=isDark();\n  const wallM=std(P.wall), wall2M=std(P.wall2), slabM=std(P.slab), deskM=std(P.desk), topM=std(P.deskTop), darkM=std(0x1b1e25,{roughness:.4});\n  const glassM=new T.MeshStandardMaterial({color:P.glass,roughness:.1,transparent:true,opacity:dk?.16:.22,depthWrite:false});\n  const frameM=std(dk?0x8a93ad:0x6b7385,{roughness:.5});\n  const fx0=floorRect.x0, fx1=floorRect.x1, fz0=floorRect.z0, fz1=floorRect.z1, fw=fx1-fx0, fd=fz1-fz0;\n  // césped, plataforma, piso\n  const lawn=new T.Mesh(new T.CylinderGeometry(Math.max(fw,fd)*3,Math.max(fw,fd)*3,.4,48),std(P.ground)); lawn.position.set(0,-.75,fd/2); lawn.receiveShadow=true; root.add(lawn);\n  root.add(box(fw+1,.5,fd+1,slabM,(fx0+fx1)/2,-.25,(fz0+fz1)/2));\n  const floor=box(fw,.12,fd,std(dk?0x2a2e3a:0xa9a498,{roughness:.9}),(fx0+fx1)/2,.0,(fz0+fz1)/2); root.add(floor);\n  // paredes de fondo y lateral (corte de maqueta)\n  root.add(box(fw,3.8,.3,wallM,(fx0+fx1)/2,1.9,fz0-.15)); root.add(box(.3,3.8,fd,wall2M,fx0-.15,1.9,(fz0+fz1)/2));\n  const bigSign=sprite(1024,160,7.2,1.125); { const x=bigSign.userData.x; rr(x,2,2,1020,156,34); x.fillStyle='rgba(18,20,28,.94)'; x.fill(); x.fillStyle='#fff'; x.font='800 78px Helvetica,Arial,sans-serif'; x.textAlign='center'; x.textBaseline='middle'; x.fillText('DEVISEBIT · OFICINA',512,84); x.fillStyle='#ff4d5e'; x.fillRect(60,132,904,8); bigSign.userData.tex.needsUpdate=true; bigSign.material.depthTest=true; }\n  bigSign.position.set(fx0+4.4,4.5,fz0+.1); root.add(bigSign);\n  // árboles y nubes\n  for(const sx of [-1,1]) for(let i=0;i<4;i++){\n    const tx=(sx<0?fx0-3.2:fx1+3.2)+sx*(i%2)*1.5, tz=fz0+3+i*(fd/3.5), h=1.8+((i*37)%5)*.25;\n    const tr=new T.Mesh(new T.CylinderGeometry(.16,.2,.8,8),std(0x6b4a2f)); tr.position.set(tx,.2,tz); tr.castShadow=true; root.add(tr);\n    for(let j=0;j<2;j++){ const c=new T.Mesh(new T.ConeGeometry(1-j*.25,h*.7,10),std(P.tree)); c.position.set(tx,.7+j*.7+h*.2,tz); c.castShadow=true; root.add(c); }\n  }\n  for(let i=0;i<5;i++){ const g=new T.Group(), cm=new T.MeshStandardMaterial({color:P.cloud,transparent:true,opacity:P.cloudOp,roughness:1});\n    for(let j=0;j<4;j++){ const s=new T.Mesh(new T.SphereGeometry(1.2+Math.random()*.8,14,10),cm); s.position.set(j*1.6-2.4,(j%2)*.5,0); s.scale.y=.55; g.add(s); }\n    g.position.set(-70+i*32+Math.random()*8,16+Math.random()*8,-18-Math.random()*20); g.userData.v=.4+Math.random()*.4; root.add(g); clouds.push(g); }\n\n  let gi=0;\n  for(const z of zs){\n    const col=new T.Color(ZCOL[gi++%ZCOL.length]); col.multiplyScalar(dk?.32:.86);\n    const carpet=box(z.w,.05,z.d,new T.MeshStandardMaterial({color:col,roughness:1}),z.cx,.08,z.cz,false); carpet.receiveShadow=true; carpet.userData.zone=z.key; root.add(carpet); hitList.push(carpet);\n    // vidrios: fondo alto, laterales bajos\n    const gb=box(z.w,2.6,.07,glassM,z.cx,1.3,z.z0,false); root.add(gb);\n    root.add(box(z.w,.08,.1,frameM,z.cx,2.62,z.z0,false));\n    for(const sx of [z.x0,z.x0+z.w]){ root.add(box(.07,1.1,z.d,glassM,sx,.6,z.cz,false)); root.add(box(.1,.08,z.d,frameM,sx,1.18,z.cz,false)); root.add(box(.1,2.6,.1,frameM,sx,1.3,z.z0,false)); }\n    const lab=makeLabel(); lab.position.set(z.x0+2.1,3.05,z.z0+.08); lab.userData.zone=z.key; root.add(lab); z.lab=lab;\n    zones[z.key]=z;\n    if(z.kind==='team') buildTeam(z,{deskM,topM,darkM});\n    else if(z.kind==='meet') buildMeet(z,{wallM,darkM,frameM});\n    else buildCafe(z,{darkM,deskM,topM});\n  }\n  // partículas\n  const N=90, pos=new Float32Array(N*3); for(let i=0;i<N;i++){ pos[i*3]=fx0+Math.random()*fw; pos[i*3+1]=Math.random()*6; pos[i*3+2]=fz0+Math.random()*fd; }\n  const pg=new T.BufferGeometry(); pg.setAttribute('position',new T.BufferAttribute(pos,3));\n  motes=new T.Points(pg,new T.PointsMaterial({color:dk?0x9db4ff:0xffffff,size:.1,transparent:true,opacity:.6})); root.add(motes);\n  sun.position.set((fx0+fx1)/2+fw*.35,26,fz1+10); sun.target.position.set((fx0+fx1)/2,0,(fz0+fz1)/2);\n  const sc=sun.shadow.camera, ext=Math.max(fw,fd)*.75; sc.left=-ext; sc.right=ext; sc.top=ext; sc.bottom=-ext; sc.near=1; sc.far=90; sc.updateProjectionMatrix();\n  buildChips(zs);\n  setFocus(focusK!=null&&zones[focusK]?focusK:null,true);\n  // posiciones iniciales\n  for(const e of ents.values()){ e.px=e.hx; e.pz=e.hz; e.away=false; e.path=[]; e.sit=1; }\n  resize();\n}\n\nfunction buildTeam(z,m){\n  z.list.forEach((a,k)=>{\n    const col=k%z.cols, row=Math.floor(k/z.cols);\n    const cx=z.cx+(col-(z.cols-1)/2)*SLOT, dz=z.z0+1.7+row*ROW;\n    const dg=new T.Group(); dg.position.set(cx,0,dz); root.add(dg);\n    const A=(o)=>{ dg.add(o); return o; };\n    A(box(1.8,.1,1.0,m.topM,0,.9,.35));\n    A(box(.1,.85,.85,m.deskM,-.8,.45,.35)); A(box(.1,.85,.85,m.deskM,.8,.45,.35)); A(box(1.6,.5,.06,m.deskM,0,.55,0,false));\n    A(box(.8,.04,.3,m.darkM,0,.97,.62,false));\n    const mug=new T.Mesh(new T.CylinderGeometry(.07,.07,.12,12),std(0xffffff)); mug.position.set(.65,1.02,.45); A(mug);\n    A(box(.09,.3,.09,m.darkM,0,1.1,.12,false)); A(box(1.0,.66,.07,m.darkM,0,1.58,.1));\n    const scrM=new T.MeshBasicMaterial({color:SC.idle}); const scr=new T.Mesh(new T.PlaneGeometry(.9,.56),scrM); scr.position.set(0,1.58,.14); A(scr);\n    const bars=[]; for(let b=0;b<3;b++){ const bm=new T.Mesh(new T.PlaneGeometry(1,.07),new T.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.75})); bm.geometry.translate(.5,0,0); bm.position.set(-.4,1.72-b*.14,.145); bm.scale.x=.4; A(bm); bars.push(bm); }\n    const seat=new T.Mesh(new T.CylinderGeometry(.42,.42,.1,16),std(0x2d313b)); seat.position.set(0,.7,-.55); seat.castShadow=true; A(seat);\n    const stem=new T.Mesh(new T.CylinderGeometry(.05,.05,.6,8),std(0x2d313b)); stem.position.set(0,.4,-.55); A(stem);\n    const bodyG=makeBody(a.look); const hx=cx, hz=dz-.5; bodyG.position.set(hx,1.95,hz); root.add(bodyG);\n    const hit=new T.Mesh(new T.BoxGeometry(1.9,2.4,1.6),new T.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false})); hit.userData.agent=a.id; root.add(hit); hitList.push(hit);\n    const bub=makeBubble(); root.add(bub); const nmS=makeName(); root.add(nmS); const badge=makeBadge(); root.add(badge);\n    const zs2=[makeZ(),makeZ()]; zs2.forEach(q=>{ q.visible=false; root.add(q); });\n    const ring=new T.Mesh(new T.RingGeometry(.85,1.0,40),new T.MeshBasicMaterial({color:SC.waiting_user,transparent:true,opacity:.7,side:T.DoubleSide})); ring.rotation.x=-Math.PI/2; ring.position.set(cx,.12,dz+.35); ring.visible=false; root.add(ring);\n    const sparks=[]; for(let s=0;s<5;s++){ const sm=new T.Mesh(new T.BoxGeometry(.08,.08,.08),new T.MeshBasicMaterial({color:0xffffff,transparent:true})); sm.visible=false; root.add(sm); sparks.push(sm); }\n    const band=null;\n    ents.set(a.id,{id:a.id,a,x:cx,dz,hx,hz,body:bodyG,hit,scrM,bars,bub,nm:nmS,badge,zs:zs2,ring,sparks,state:'',paso:'',tk:-1,ph:(k*1.7+z.cx*.3)%6.28,piso:String(z.piso),zone:z,gi:0,rotY:0});\n  });\n}\n\nfunction buildMeet(z,m){\n  // mesa larga, sillas, pantalla y holograma\n  const tm=std(0xb48b5c);\n  root.add(box(4.6,.14,1.7,tm,z.cx,.95,z.cz+.4)); root.add(box(.3,.9,1.2,m.darkM,z.cx-1.7,.5,z.cz+.4)); root.add(box(.3,.9,1.2,m.darkM,z.cx+1.7,.5,z.cz+.4));\n  for(let i=0;i<6;i++){ const sx=z.cx+(i%3-1)*1.4, sz=z.cz+.4+(i<3?-1.3:1.3); const c=new T.Mesh(new T.CylinderGeometry(.34,.34,.1,14),std(0x2d313b)); c.position.set(sx,.6,sz); c.castShadow=true; root.add(c); const bk=box(.6,.5,.08,std(0x2d313b),sx,.95,sz+(i<3?-.3:.3)); root.add(bk); }\n  const cv2=document.createElement('canvas'); cv2.width=768; cv2.height=384; const tex=new T.CanvasTexture(cv2);\n  const scr=new T.Mesh(new T.PlaneGeometry(4.2,2.1),new T.MeshBasicMaterial({map:tex})); scr.position.set(z.cx,2.0,z.z0+.3); root.add(scr);\n  root.add(box(4.4,2.3,.08,m.darkM,z.cx,2.0,z.z0+.24,false));\n  meetScr={cv:cv2,x:cv2.getContext('2d'),tex,last:''};\n  holo=new T.Mesh(new T.IcosahedronGeometry(.45,0),new T.MeshBasicMaterial({color:0xff4d5e,wireframe:true})); holo.position.set(z.cx,1.75,z.cz+.4); root.add(holo);\n  const plate=new T.Mesh(new T.CylinderGeometry(.5,.5,.04,20),new T.MeshBasicMaterial({color:0xff4d5e,transparent:true,opacity:.5})); plate.position.set(z.cx,1.04,z.cz+.4); root.add(plate);\n  // puerta (hueco) marcada en piso\n  z.holo=holo;\n}\nfunction drawMeet(n){\n  if(!meetScr) return; const key=JSON.stringify(n)+isDark(); if(key===meetScr.last) return; meetScr.last=key;\n  const x=meetScr.x; x.fillStyle='#10131b'; x.fillRect(0,0,768,384);\n  x.fillStyle='#ff4d5e'; x.fillRect(0,0,768,10);\n  x.fillStyle='#fff'; x.font='800 44px Helvetica,Arial,sans-serif'; x.textAlign='left'; x.textBaseline='middle'; x.fillText('REUNIÓN DE GABINETE',34,62);\n  const rows=[['Para tu OK',n.p,'#f5a524'],['Órdenes nuevas',n.n,'#5aa2ff'],['En reparto',n.a,'#3dd598']];\n  rows.forEach((r,i)=>{ const y=150+i*76; x.fillStyle='#1c212d'; rr(x,34,y-30,700,60,14); x.fill(); x.fillStyle=r[2]; x.beginPath(); x.arc(70,y,12,0,7); x.fill(); x.fillStyle='#e6e9f0'; x.font='600 34px Helvetica,Arial,sans-serif'; x.textAlign='left'; x.fillText(r[0],100,y+2); x.textAlign='right'; x.font='800 44px Helvetica,Arial,sans-serif'; x.fillText(String(r[1]),712,y+2); });\n  meetScr.tex.needsUpdate=true;\n}\n\nfunction buildCafe(z,m){\n  const sofaM=std(0xd7263d), cushion=std(0xe5516a), plant=std(0x3fa66a), pot=std(0xb0764a);\n  root.add(box(3.4,.55,1.2,sofaM,z.x0+2.4,.35,z.z0+1.0)); root.add(box(3.4,.9,.3,sofaM,z.x0+2.4,.75,z.z0+.5)); root.add(box(.3,.7,1.2,sofaM,z.x0+.8,.5,z.z0+1.0)); root.add(box(.3,.7,1.2,sofaM,z.x0+4.0,.5,z.z0+1.0));\n  root.add(box(1.4,.08,.8,std(0xb48b5c),z.x0+2.4,.45,z.z0+2.4)); \n  for(const [px,pz] of [[z.x0+.7,z.z0+z.d-.8],[z.x0+z.w-.7,z.z0+z.d-.8],[z.x0+z.w-.7,z.z0+.8]]){ const p=new T.Mesh(new T.CylinderGeometry(.35,.28,.55,12),pot); p.position.set(px,.3,pz); p.castShadow=true; root.add(p); for(let i=0;i<3;i++){ const l=new T.Mesh(new T.SphereGeometry(.34-i*.05,12,10),plant); l.position.set(px+(i-1)*.1,.8+i*.35,pz); l.castShadow=true; root.add(l); } }\n  // cafetera\n  root.add(box(.8,1.3,.7,m.darkM,z.x0+z.w-1.5,.7,z.z0+.7)); root.add(box(.5,.12,.04,new T.MeshBasicMaterial({color:0xff4d5e}),z.x0+z.w-1.5,1.1,z.z0+1.06,false));\n  // ping-pong\n  const tx=z.cx+1.6, tz=z.cz+.6;\n  root.add(box(3.0,.1,1.6,std(0x1e7a52),tx,.95,tz)); root.add(box(3.0,.02,.04,std(0xffffff),tx,1.01,tz,false)); root.add(box(.04,.22,1.7,new T.MeshStandardMaterial({color:0xffffff,transparent:true,opacity:.6}),tx,1.1,tz,false));\n  for(const sx of [-1.3,1.3]) for(const sz of [-.65,.65]) root.add(box(.1,.9,.1,m.darkM,tx+sx,.5,tz+sz,false));\n  ball=new T.Mesh(new T.SphereGeometry(.08,10,8),new T.MeshBasicMaterial({color:0xffffff})); ball.position.set(tx,1.1,tz); ball.userData.c=[tx,tz]; root.add(ball);\n  // puntos de descanso\n  const S0=[[z.x0+1.6,z.z0+2.6],[z.x0+3.2,z.z0+3.6],[z.x0+1.4,z.z0+4.6],[z.x0+4.8,z.z0+2.6],[tx-2.4,tz],[tx+2.4,tz],[tx-1.0,tz+1.7],[tx+1.0,tz+1.7],[tx-1.0,tz-1.6],[tx+1.0,tz-1.6],[z.x0+z.w-2.2,z.z0+2.6],[z.x0+z.w-3.4,z.z0+4.2]];\n  spots=S0.map(p=>({x:Math.min(z.x0+z.w-.8,Math.max(z.x0+.8,p[0])),z:Math.min(z.z0+z.d-.8,Math.max(z.z0+.8,p[1]))}));\n}\n\n/* ---------- cámara y foco ---------- */\nconst PITCH=.86;\nfunction fit(w,d){ const t=Math.tan(T.MathUtils.degToRad(cam.fov/2)); const byW=w*1.08/(2*t*cam.aspect), byH=(d*Math.sin(PITCH)+4.2*Math.cos(PITCH))*1.1/(2*t); return Math.max(byW,byH)+2; }\nfunction setFocus(k,snap){\n  if(k!=null&&!zones[k]) k=null;\n  focusK=k;\n  if(k==null){ const w=floorRect.x1-floorRect.x0, d=floorRect.z1-floorRect.z0; tgt.tx=(floorRect.x0+floorRect.x1)/2; tgt.tz=(floorRect.z0+floorRect.z1)/2; tgt.dist=fit(w+2,d+1); }\n  else { const z=zones[k]; tgt.tx=z.cx; tgt.tz=z.cz+.4; tgt.dist=fit(z.w+1.2,z.d+.4); }\n  if(snap){ cur.tx=tgt.tx; cur.tz=tgt.tz; cur.dist=tgt.dist; }\n  syncChips();\n}\nfunction buildChips(zs){\n  chips.innerHTML='<button type=\"button\" class=\"chip3\" data-p=\"all\">Toda la oficina</button>'+zs.map(z=>'<button type=\"button\" class=\"chip3\" data-p=\"'+esc(z.key)+'\">'+esc(z.name)+(z.kind==='team'?' <b data-cnt=\"'+esc(z.key)+'\"></b>':'')+'</button>').join('');\n}\nfunction syncChips(){ chips.querySelectorAll('.chip3').forEach(b=>{ const on=(b.dataset.p==='all')?focusK==null:b.dataset.p===focusK; b.setAttribute('aria-pressed',on?'true':'false'); }); }\nchips.addEventListener('click',ev=>{ const b=ev.target.closest('.chip3'); if(!b) return; yawOff=0; setFocus(b.dataset.p==='all'?null:b.dataset.p); });\n\n/* ---------- estados y recorridos ---------- */\nfunction aisleOf(e){ const b=e.zone; return b.z0+b.d+GAPZ/2; }\nfunction goAway(e){\n  const sp=spots[e.gi%Math.max(1,spots.length)]; if(!sp) return;\n  const ai=aisleOf(e), sx=e.hx+SLOT/2;\n  e.path=[{x:sx,z:e.pz>e.hz+.1?e.pz:e.hz},{x:sx,z:ai},{x:corrX,z:ai},{x:corrX,z:cafeAisle},{x:sp.x,z:cafeAisle},{x:sp.x,z:sp.z}];\n  e.away=true;\n}\nfunction goHome(e){\n  const ai=aisleOf(e), sx=e.hx+SLOT/2;\n  e.path=[{x:e.px,z:cafeAisle},{x:corrX,z:cafeAisle},{x:corrX,z:ai},{x:sx,z:ai},{x:sx,z:e.hz},{x:e.hx,z:e.hz}];\n  e.away=false;\n}\nfunction applyState(e,s,tk){\n  const col=SC[s.k]||SC.idle, k=s.k;\n  const idleTxt=k==='none'?'Todavía no reportó':(k==='idle'?'Descansando…':'');\n  const txt=s.paso||idleTxt||(e.a.rol||'');\n  e.bub.userData.set(txt,col);\n  e.nm.userData.set(e.a.nombre||e.id,STT[k]+(tk?' · '+tk+' tarea'+(tk>1?'s':''):''),col);\n  e.scrM.color.set((k==='none'||k==='idle')?'#2a2f3a':col);\n  const g=e.body.userData; g.mat.color.copy(g.base); if(k==='none') g.mat.color.lerp(new T.Color(0x9aa0aa),.45);\n  const rest=(k==='idle'||k==='none');\n  g.eyes.scale.y=rest?.25:1;\n  const glyph={waiting_user:'!',error:'×',done:'✓'}[k];\n  e.badge.visible=!!glyph; if(glyph) drawBadge(e.badge,col,glyph);\n  e.ring.visible=k==='waiting_user'; e.ring.material.color.set(col);\n  e.sparks.forEach(m=>m.material.color.set(k==='error'?'#7c818d':col));\n  if(rest&&!e.away&&spots.length) goAway(e); else if(!rest&&e.away) goHome(e);\n  if(!e.init){ e.init=1; if(e.away&&e.path.length){ const l=e.path[e.path.length-1]; e.px=l.x; e.pz=l.z; e.path=[]; e.sit=0; } }\n  e.state=k; e.paso=s.paso; e.tk=tk;\n}\nlet lastSig='';\nwindow.sync3D=function(lat){\n  if(!S.agentes.length){ stage.hidden=true; return; }\n  stage.hidden=false; if(!view3d) return;\n  const sig=JSON.stringify(S.agentes.map(a=>[a.id,a.piso,a.orden,a.nombre,a.look]))+isDark();\n  if(sig!==lastSig){ lastSig=sig; build(); S.agentes.forEach((a,i)=>{ const e=ents.get(a.id); if(e) e.gi=i; }); }\n  const cnt={}, tot={};\n  for(const a of S.agentes){ const e=ents.get(a.id); if(!e) continue; const s=stateOf(a,lat), tk=tareasDe(a.id).length;\n    tot[a.piso]=(tot[a.piso]||0)+1; if(s.k==='working') cnt[a.piso]=(cnt[a.piso]||0)+1;\n    if(e.state!==s.k||e.paso!==s.paso||e.tk!==tk) applyState(e,s,tk); }\n  for(const k in zones){ const z=zones[k]; if(z.kind==='team') z.lab.userData.set(z.name,(cnt[z.piso]||0)+' de '+(tot[z.piso]||0)+' trabajando',(cnt[z.piso]?SC.working:SC.idle)); else if(z.kind==='meet') z.lab.userData.set(z.name,'',SC.waiting_user); else z.lab.userData.set(z.name,'',SC.done); }\n  chips.querySelectorAll('[data-cnt]').forEach(b=>{ const n=cnt[b.dataset.cnt]||0; b.textContent=n?('· '+n+' ▸'):''; });\n  const o=S.ordenes||[]; drawMeet({p:o.filter(x=>x.estado==='propuesta').length,n:o.filter(x=>x.estado==='nueva').length,a:o.filter(x=>x.estado==='aprobada'||x.estado==='repartida').length});\n};\n\n/* ---------- vista 3D / lista ---------- */\nlet view3d=true;\ntry{ if(localStorage.getItem('oficina-vista')==='lista') view3d=false; }catch(e){}\nfunction applyView(){\n  cv.parentElement.querySelectorAll('.only3d').forEach(el=>el.hidden=!view3d);\n  flo.hidden=view3d; tgl.textContent=view3d?'Ver como lista':'Ver en 3D';\n  if(view3d) lastSig='';\n  try{ renderAll(); }catch(e){}\n}\ntgl.addEventListener('click',()=>{ view3d=!view3d; try{ localStorage.setItem('oficina-vista',view3d?'3d':'lista'); }catch(e){} applyView(); });\n\n/* ---------- interacción ---------- */\nconst ray=new T.Raycaster(), v2=new T.Vector2();\nlet drag=null; const el=renderer.domElement;\nel.addEventListener('pointerdown',ev=>{ drag={x:ev.clientX,yo:yawOff,moved:false}; try{el.setPointerCapture(ev.pointerId);}catch(e){} });\nel.addEventListener('pointermove',ev=>{ if(!drag) return; const dx=ev.clientX-drag.x; if(Math.abs(dx)>6) drag.moved=true; if(drag.moved) yawOff=Math.max(-1.0,Math.min(1.0,drag.yo-dx*.005)); });\nel.addEventListener('pointerup',ev=>{\n  const d=drag; drag=null; if(!d||d.moved) return;\n  const r=el.getBoundingClientRect(); v2.set(((ev.clientX-r.left)/r.width)*2-1,-((ev.clientY-r.top)/r.height)*2+1);\n  ray.setFromCamera(v2,cam); const hits=ray.intersectObjects(hitList,false); if(!hits.length) return;\n  const h=hits.find(x=>x.object.userData.agent)||hits[0], u=h.object.userData;\n  if(u.agent){ const e=ents.get(u.agent); if(focusK!=null||cv.clientWidth>=760){ S.sel=u.agent; $('sheet').hidden=false; renderSheet(); } else if(e){ setFocus(e.away?'cafe':e.piso); } }\n  else if(u.zone!=null){ setFocus(u.zone); }\n});\nel.addEventListener('pointercancel',()=>{ drag=null; });\nel.addEventListener('dblclick',()=>{ yawOff=0; setFocus(null); });\n\n/* ---------- tamaño y bucle ---------- */\nfunction resize(){\n  const w=cv.clientWidth, h=cv.clientHeight; if(!w||!h) return;\n  renderer.setSize(w,h,false); el.style.width='100%'; el.style.height='100%';\n  cam.aspect=w/h; cam.updateProjectionMatrix();\n  if(root) setFocus(focusK,true);\n}\nnew ResizeObserver(resize).observe(cv);\nlet vis=true; new IntersectionObserver(es=>{ vis=es[0].isIntersecting; }).observe(cv);\nlet tPrev=performance.now(); const t0=tPrev;\nfunction loop(now){\n  requestAnimationFrame(loop);\n  if(!vis||document.hidden||!root||!view3d){ tPrev=now; return; }\n  const t=(now-t0)/1000, dt=Math.min(.05,(now-tPrev)/1000); tPrev=now;\n  const k=1-Math.pow(.001,dt);\n  cur.tx+=(tgt.tx-cur.tx)*k*.9; cur.tz+=(tgt.tz-cur.tz)*k*.9; cur.dist+=(tgt.dist-cur.dist)*k*.9;\n  const yaw=yawOff+(drag?0:Math.sin(t*.22)*.05*M);\n  cam.position.set(cur.tx+Math.sin(yaw)*Math.cos(PITCH)*cur.dist,.6+Math.sin(PITCH)*cur.dist,cur.tz+Math.cos(yaw)*Math.cos(PITCH)*cur.dist);\n  cam.lookAt(cur.tx,.6,cur.tz);\n  const wide=cv.clientWidth>=760;\n  for(const e of ents.values()){\n    const st=e.state, ph=e.ph;\n    // movimiento por el recorrido\n    let moving=false;\n    if(e.path&&e.path.length){ const w=e.path[0], dx=w.x-e.px, dz=w.z-e.pz, dist=Math.hypot(dx,dz), step=4.6*dt; moving=true;\n      if(dist<=step){ e.px=w.x; e.pz=w.z; e.path.shift(); } else { e.px+=dx/dist*step; e.pz+=dz/dist*step; const ang=Math.atan2(dx,dz); let da=ang-e.rotY; da=Math.atan2(Math.sin(da),Math.cos(da)); e.rotY+=da*Math.min(1,dt*10); } }\n    if(!moving){ let da=-e.rotY; e.rotY+=da*Math.min(1,dt*8); }\n    const seated=!moving&&!e.away; e.sit+=((seated?1:0)-e.sit)*Math.min(1,dt*6);\n    let dy=0,rz=0,dx2=0,sy=1;\n    if(moving){ dy=Math.abs(Math.sin(t*13+ph))*.14*Math.max(M,.5); rz=Math.sin(t*13+ph)*.08*Math.max(M,.5); }\n    else if(st==='working'){ dy=Math.abs(Math.sin(t*8+ph))*.07*M; rz=Math.sin(t*8+ph)*.04*M; }\n    else if(st==='waiting_user'){ dy=Math.abs(Math.sin(t*3+ph))*.35*M; rz=Math.sin(t*6)*.12*M; }\n    else if(st==='done'){ dy=Math.abs(Math.sin(t*1.6+ph))*.18*M; }\n    else if(st==='error'){ dx2=Math.sin(t*40)*.05*M; }\n    else { sy=1+Math.sin(t*1.5+ph)*.03*M; }\n    const by=.62+1.33*e.sit;\n    e.body.position.set(e.px+dx2,by+dy,e.pz); e.body.rotation.y=e.rotY; e.body.rotation.z=rz; e.body.userData.inner.scale.y=sy;\n    e.hit.position.set(e.px,by,e.pz);\n    for(let i=0;i<3;i++){ const b=e.bars[i]; b.scale.x=st==='working'?.25+.75*Math.abs(Math.sin(t*3+i*1.7+ph)):.35+i*.1; b.material.opacity=(st==='working')?.85:.3; }\n    if(st==='working'){ e.scrM.color.set(SC.working).multiplyScalar(.8+.2*Math.sin(t*6+ph)); }\n    const bv=focusK==null?wide:(focusK==='cafe'?e.away:(!e.away&&e.piso===focusK));\n    e.bub.visible=bv; e.nm.visible=bv;\n    e.bub.position.set(e.px,by+1.35,e.pz+.4);\n    e.nm.position.set(e.px,e.sit>.5?.45:.5,e.sit>.5?e.dz+.98:e.pz+.95);\n    if(e.badge.visible) e.badge.position.set(e.px+.7,by+.95+Math.sin(t*4+ph)*.07*M,e.pz+.4);\n    if(e.ring.visible){ const s=1+((t*.9+ph)%1)*.5; e.ring.scale.set(s,s,s); e.ring.material.opacity=.7*(1-((t*.9+ph)%1)); }\n    const sz=(st==='idle'||st==='none')&&!moving;\n    e.zs.forEach((z,i)=>{ z.visible=sz; if(sz){ const u=(t*.3+i*.5+ph*.1)%1; z.position.set(e.px+.55+u*.35,by+.8+u*.8,e.pz+.3); z.material.opacity=Math.sin(u*Math.PI); } });\n    const sp=(st==='working'||st==='error')&&seated;\n    e.sparks.forEach((m,i)=>{ m.visible=sp; if(sp){ const u=(t*(st==='error'?.5:.8)+i*.2+ph)%1; if(st==='error'){ m.position.set(e.px+(i-2)*.12,by+.7+u*.8,e.pz+.1); m.scale.setScalar(1.6-u); } else { m.position.set(e.x+(i-2)*.18,2.0+u*1.0,e.dz+.2); m.rotation.set(u*6,u*4,0); m.scale.setScalar(1.2-u*.7); } m.material.opacity=1-u; } });\n  }\n  if(holo){ holo.rotation.y=t*1.2; holo.rotation.x=t*.7; holo.position.y=1.75+Math.sin(t*2)*.08*M; }\n  if(ball){ const c=ball.userData.c; ball.position.set(c[0]+Math.sin(t*3)*1.3,1.12+Math.abs(Math.cos(t*3))*.4*M,c[1]+Math.sin(t*1.3)*.25); }\n  clouds.forEach(c=>{ c.position.x+=c.userData.v*dt*M; if(c.position.x>90) c.position.x=-90; });\n  if(motes){ const a=motes.geometry.attributes.position; for(let i=0;i<a.count;i++){ let y=a.getY(i)+.004*M; if(y>6) y=0; a.setY(i,y); a.setX(i,a.getX(i)+Math.sin(t+i)*.0015*M); } a.needsUpdate=true; }\n  renderer.render(scene,cam);\n}\nrequestAnimationFrame(loop);\nmatchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{ lastSig=''; schedule(); });\nnew MutationObserver(()=>{ lastSig=''; schedule(); }).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});\napplyView();\n})();\n</script>\n<script>\n/* Dictado por voz (el navegador transcribe; no se guarda el audio) y cambio de nombre de las personas del equipo */\n(function(){\n  var SR=window.SpeechRecognition||window.webkitSpeechRecognition, mic=document.getElementById('ordmic'), txt=document.getElementById('ordtxt');\n  if(SR&&mic&&txt){\n    mic.hidden=false; var rec=null, base='';\n    mic.addEventListener('click',function(){\n      if(rec){ rec.stop(); return; }\n      rec=new SR(); rec.lang='es-AR'; rec.interimResults=true; rec.continuous=true; base=txt.value?txt.value.replace(/\\s+$/,'')+' ':'';\n      rec.onresult=function(e){ var t=''; for(var i=0;i<e.results.length;i++) t+=e.results[i][0].transcript; txt.value=(base+t).slice(0,1500); };\n      rec.onend=function(){ rec=null; mic.setAttribute('aria-pressed','false'); mic.textContent='Dictar con el micrófono'; };\n      rec.onerror=function(){ };\n      mic.setAttribute('aria-pressed','true'); mic.textContent='Escuchando… tocá para terminar'; rec.start();\n    });\n  }\n  var nb=document.getElementById('pnsave');\n  if(nb) nb.addEventListener('click',function(){\n    var v=document.getElementById('pnom').value.trim(), er=document.getElementById('perr'); er.hidden=true;\n    if(!v||!S.sel) return; nb.disabled=true;\n    S.db.doc('agentes/'+S.sel).update({nombre:v}).then(function(){ var a=S.agentes.find(function(x){ return x.id===S.sel; }); if(a) a.nombre=v; document.getElementById('sh-title').textContent=v; if(window.renderAll) window.renderAll(); }).catch(function(){ er.hidden=false; er.textContent='No se pudo cambiar el nombre.'; }).then(function(){ nb.disabled=false; });\n  });\n})();\n\n/* Llamada de voz gratis: el navegador escucha y habla; el jefe responde con la propuesta */\n(function(){\n  var SR=window.SpeechRecognition||window.webkitSpeechRecognition, btn=document.getElementById('ordcall'), ss=window.speechSynthesis;\n  if(!SR||!ss||!btn) return; btn.hidden=false;\n  var on=false, rec=null;\n  function say(t){ return new Promise(function(ok){ try{ ss.cancel(); var u=new SpeechSynthesisUtterance(t); u.lang='es-AR'; u.rate=1.03; u.onend=ok; u.onerror=ok; ss.speak(u); }catch(e){ ok(); } }); }\n  function listen(){ return new Promise(function(ok){ var got='', r=new SR(); rec=r; r.lang='es-AR'; r.interimResults=false; r.continuous=false;\n    r.onresult=function(e){ for(var i=0;i<e.results.length;i++) got+=e.results[i][0].transcript+' '; };\n    r.onend=function(){ rec=null; ok(got.trim()); }; r.onerror=function(){ }; try{ r.start(); }catch(e){ ok(''); } }); }\n  function last(){ return (S.ordenes||[]).find(function(o){ return o.estado==='propuesta'; }); }\n  function wait(id){ return new Promise(function(ok){ var n=0; (function t(){ var o=(S.ordenes||[]).find(function(x){ return x.id===id; }); if((o&&o.estado!=='nueva')||++n>24) return ok(o); setTimeout(t,2500); })(); }); }\n  function setUI(){ btn.setAttribute('aria-pressed',on?'true':'false'); btn.textContent=on?'Colgar':'Llamar al jefe (voz)'; }\n  async function loop(){\n    await say('Hola Julio, soy el jefe de gabinete. Decime qué necesitás.');\n    var miss=0;\n    while(on){\n      var t=await listen(); if(!on) break;\n      if(!t){ if(++miss>=3){ await say('No te escucho. Corto. Cuando quieras, volvé a llamar.'); break; } continue; } miss=0;\n      var l=t.toLowerCase();\n      if(/\\b(chau|cort[aá]|colg[aá]|nada m[aá]s|eso es todo|listo gracias)\\b/.test(l)){ await say('Dale, chau.'); break; }\n      var p=last();\n      if(p&&/^(s[ií]|dale|ok|okey|aprob[aá]|aprobado|confirmo|hacelo|mandale)\\b/.test(l)){ try{ await S.db.doc('ordenes/'+p.id).update({estado:'aprobada',decidida:new Date().toISOString()}); await say('Aprobado. Reparto las tareas.'); }catch(e){ await say('No pude aprobar. Probá desde la pantalla.'); } continue; }\n      if(p&&/^(no\\b|rechaz|cancel|dej[aá])/.test(l)){ try{ await S.db.doc('ordenes/'+p.id).update({estado:'rechazada',decidida:new Date().toISOString()}); await say('Listo, la descarté.'); }catch(e){ await say('No pude rechazarla.'); } continue; }\n      try{\n        var r=await S.db.collection('ordenes').add({texto:t.slice(0,1500),canal:'voz'}); say('Anotado. Lo estoy pensando.');\n        var o=await wait(r.id); ss.cancel();\n        if(o&&o.estado!=='nueva'){ await say((o.resumen||'Quedó propuesta.')+' ¿Lo apruebo?'); } else { await say('Todavía lo estoy pensando. Miralo en pantalla en un ratito.'); }\n      }catch(e){ await say('No pude anotarlo. Probá de nuevo.'); }\n    }\n    on=false; setUI(); try{ ss.cancel(); }catch(e){}\n  }\n  btn.addEventListener('click',function(){ if(on){ on=false; try{ if(rec) rec.stop(); ss.cancel(); }catch(e){} setUI(); return; } on=true; setUI(); loop(); });\n})();\n</script>\n</html>"
